begin;
select no_plan();
-- Isolated synthetic records; the enclosing transaction rolls every write back.
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values
('d1000000-0000-4000-8000-000000000001','development-parent@example.test','{"name":"Parent"}',now()),
('d1000000-0000-4000-8000-000000000002','development-coach@example.test','{"name":"Coach"}',now()),
('d1000000-0000-4000-8000-000000000003','development-reviewer@example.test','{"name":"Reviewer"}',now()),
('d1000000-0000-4000-8000-000000000004','development-other@example.test','{"name":"Other"}',now());
insert into public.role_assignments values ('d1000000-0000-4000-8000-000000000002','coach'),('d1000000-0000-4000-8000-000000000003','super_admin');
insert into public.branches(id,slug,name,provisional) values('d2000000-0000-4000-8000-000000000001','development-test','Synthetic development',false);
insert into public.branch_permissions values('d1000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000001');
insert into public.venues(id,branch_id,name,address) values('d2000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000001','Test pool','Synthetic');
insert into public.sport_levels(id,sport,name,rank) values('d2000000-0000-4000-8000-000000000003','swimming','Development beginner',10),('d2000000-0000-4000-8000-000000000004','swimming','Development next',11);
insert into public.age_groups(id,name,min_age,max_age) values('d2000000-0000-4000-8000-000000000005','Development ages',5,10);
insert into public.academy_classes(id,branch_id,venue_id,coach_id,sport,level_id,age_group_id,name,capacity,weekdays,local_time,duration_minutes) values('d2000000-0000-4000-8000-000000000006','d2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000002','swimming','d2000000-0000-4000-8000-000000000003','d2000000-0000-4000-8000-000000000005','Development session',10,array[0],'17:00',60);
insert into public.class_sessions(id,class_id,starts_at,ends_at,capacity) values('d2000000-0000-4000-8000-000000000007','d2000000-0000-4000-8000-000000000006',now()-interval '2 hours',now()-interval '1 hour',10);
insert into public.families(id,name) values('d3000000-0000-4000-8000-000000000001','Development family');
insert into public.guardians values('d3000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001');
insert into public.children(id,family_id,name,reported_age,age_captured_on) values('d3000000-0000-4000-8000-000000000002','d3000000-0000-4000-8000-000000000001','Synthetic Athlete',7,current_date);
insert into public.child_sports(child_id,sport,level_id,level,status) values('d3000000-0000-4000-8000-000000000002','swimming','d2000000-0000-4000-8000-000000000003','Development beginner','reviewed');
insert into public.enrollments(id,child_id,class_id) values('d3000000-0000-4000-8000-000000000003','d3000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000006');
insert into public.session_roster(session_id,enrollment_id,kind,attendance) values('d2000000-0000-4000-8000-000000000007','d3000000-0000-4000-8000-000000000003','enrollment','present');
create function pg_temp.dev_cmd(a text,d jsonb) returns jsonb language sql as $$select public.product_command(a,d,gen_random_uuid())$$;
grant execute on function pg_temp.dev_cmd(text,jsonb) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Development skills","criteria":[{"key":"distance","label":"Distance","unit":"m","min":0,"max":100,"direction":"higher"}]}')$$,'Reviewer configures versioned sport criteria');
select lives_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Development skills revision","criteria":[{"key":"distance","label":"Distance","unit":"m","min":0,"max":200,"direction":"higher"}]}')$$,'Criteria revision creates another version');
select is((select max(version) from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003'),2,'Version history retained');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is(jsonb_array_length(public.development_sessions()),1,'Assigned coach sees session projection');
select ok(not (public.development_sessions()::text like '%family_id%'),'Coach projection omits family identifiers and contact');
select throws_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Unauthorized","criteria":[]}')$$,'42501',null,'Coach cannot configure standards');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','criteria_id',(select id from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003' and version=1),'scores','{"distance":101}'::jsonb,'summary','Too far'))$$,'22023',null,'Assessment range validated against exact version');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('next_target',repeat('x',1001)))$$,'22023',null,'SQL enforces bounded next training target before authoring');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','criteria_id',(select id from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003' and version=1),'scores','{"distance":25}'::jsonb,'summary','Improved confidence','next_target','Practice the reviewed 25 metre technique.','internal_note','Private coaching note','recommended_level_id','d2000000-0000-4000-8000-000000000004'))$$,'Assigned coach saves draft');
select set_config('test.assessment',(select id::text from public.development_assessments where child_id='d3000000-0000-4000-8000-000000000002'),true);
select is((select count(*)::int from public.development_assessment_notes where assessment_id=current_setting('test.assessment')::uuid),1,'Coach can read private notes');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_assessments where child_id='d3000000-0000-4000-8000-000000000002'),0,'Parent cannot see draft');
select is((select count(*)::int from public.development_assessment_notes),0,'Parent cannot see private notes');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.submit',jsonb_build_object('id',current_setting('test.assessment')))$$,'42501',null,'Parent cannot submit draft');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.assessment.submit',jsonb_build_object('id',current_setting('test.assessment')))$$,'Coach submits completed evidence');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.review',jsonb_build_object('id',current_setting('test.assessment'),'decision','approved','reason','Reviewed evidence'))$$,'42501',null,'Coach cannot approve own assessment');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select pg_temp.dev_cmd('development.assessment.publish',jsonb_build_object('id',current_setting('test.assessment')))$$,'P0409',null,'Submission cannot bypass review');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.review',jsonb_build_object('id',current_setting('test.assessment'),'decision','approved','reason','Evidence checked'))$$,'Independent reviewer approves');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.publish',jsonb_build_object('id',current_setting('test.assessment')))$$,'Reviewer publishes');
select lives_ok($$select pg_temp.dev_cmd('development.level.approve',jsonb_build_object('assessment_id',current_setting('test.assessment'),'reason','Ready for next level'))$$,'Published recommendation can be approved');

reset role;
update public.branches set synthetic=true where id='d2000000-0000-4000-8000-000000000001';
update public.families set synthetic=true where id='d3000000-0000-4000-8000-000000000001';
update public.children set synthetic=true where id='d3000000-0000-4000-8000-000000000002';
update public.profiles set synthetic=true where id in('d1000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000003');
update public.class_sessions set starts_at=date_trunc('month',now())-interval '5 days',ends_at=date_trunc('month',now())-interval '5 days'+interval '1 hour' where id='d2000000-0000-4000-8000-000000000007';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2","iss":"http://127.0.0.1:56321/auth/v1"}',true);
select lives_ok($$select public.scheduler_configure('d2000000-0000-4000-8000-000000000001',true,'kafou-local','Isolated synthetic automation test')$$,'Owner authorizes synthetic worker');
select lives_ok($$select public.development_automation_configure('d2000000-0000-4000-8000-000000000001','monthly_report',true,'Monthly factual draft')$$,'Owner configures versioned monthly policy');
select lives_ok($$select public.development_automation_configure('d2000000-0000-4000-8000-000000000001','completion_certificate',true,'Completed approved sport level')$$,'Owner configures completion trigger');
reset role;
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select private.run_scheduled_jobs('kafou-local',20)$$,'Existing worker executes development jobs without user JWT');
select is((select count(*)::int from public.development_reports where automation_policy_id is not null),1,'One monthly draft created');
select is((select status from public.development_reports where automation_policy_id is not null),'draft','Generated report remains draft');
select is((select count(*)::int from public.product_events where kind='development.report.published'),0,'Draft does not notify parents');
select is((select count(*)::int from public.development_certificates where automation_policy_id is not null),1,'Approved progression produces one certificate');
select lives_ok($$select private.run_scheduled_jobs('kafou-local',20)$$,'Repeated worker tick succeeds');
select is((select count(*)::int from public.development_reports where automation_policy_id is not null),1,'Draft dedupe persists across ticks');
select is((select count(*)::int from public.development_certificates where automation_policy_id is not null),1,'Certificate dedupe persists across ticks');
select is((select count(*)::int from private.scheduled_job_runs where outcome='succeeded'),2,'Both effects retain durable run history');
select is((select count(*)::int from public.delivery_outbox where status<>'not_configured'),0,'External delivery remains inactive');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_reports),0,'Parent cannot read generated draft');
select is((select count(*)::int from public.development_certificates),1,'Parent downloads generated certificate through existing access');
select throws_ok($$select public.development_automation_configure('d2000000-0000-4000-8000-000000000001','monthly_report',false,'Parent policy attack')$$,'42501',null,'Parent cannot disable policy');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.report.submit',jsonb_build_object('id',(select id from public.development_reports where automation_policy_id is not null)))$$,'Assigned coach can submit generated draft');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.report.review',jsonb_build_object('id',(select id from public.development_reports where automation_policy_id is not null),'decision','approved','reason','Reviewed factual evidence'))$$,'Independent reviewer approves draft');
select lives_ok($$select pg_temp.dev_cmd('development.report.publish',jsonb_build_object('id',(select id from public.development_reports where automation_policy_id is not null)))$$,'Only explicit publication notifies parent');
select lives_ok($$select pg_temp.dev_cmd('development.level.reverse',jsonb_build_object('id',(select id from public.development_level_history where assessment_id=current_setting('test.assessment')::uuid),'reason','Synthetic reviewed correction'))$$,'Reversal uses existing immutable correction workflow');
select is((select count(*)::int from public.development_certificates),0,'Reversal immediately withdraws automated certificate access');
reset role;
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select private.run_scheduled_jobs('kafou-local',20)$$,'Tick after reversal does not revive certificate');
select is((select count(*)::int from public.development_certificates),1,'Original issued certificate retained without duplicate');
select * from finish();rollback;
